$owner=$pf->owner();$created=$owner->provision(9101,'new.person@shlz.ru','New Person');assertSameValue('created',$created['status'],'provision');$id=$created['userId'];
assertSameValue('activated',$owner->setInitialPassword('new.person@shlz.ru',PasswordAccessFixture::PASSWORD,PasswordAccessFixture::PASSWORD)['status'],'initial password');
assertSameValue(303,$f->login($recipient,'new.person@shlz.ru',PasswordAccessFixture::PASSWORD)['status'],'recipient login');
