$before=$f->facts();assertSameValue('invalid',$owner->provision(9101,'new.person@shlz.ru','Duplicate')['status'],'duplicate invalid');assertSameValue('invalid',$owner->reissue(9101,$id)['status'],'retired reissue rejected');assertSameValue($before,$f->facts(),'duplicate/reissue no facts');
